"use client"
import { FolderIcon, FolderPlusIcon, SearchIcon, SearchXIcon } from "lucide-react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import {
  ListItem,
  ListItemMedia,
  ListItemContent,
  ListItemTitle,
  ListItemDescription,
} from "@atlas/ui-web/compositions/ListItem/ListItem"
import { TabsRoot, TabsList, TabsTrigger } from "@atlas/ui-web/patterns/Tabs/Tabs"
import { FlowShell } from "../_shared/FlowShell"
import { useFlowState } from "../_shared/useFlowState"
import { EmptyState } from "./EmptyState"
import { NO_MATCH_QUERY, PROJECTS, PROJECTS_INITIAL, type ProjectsData, type ProjectsView } from "./schema"

export default function EmptyStatePage() {
  const flow = useFlowState<ProjectsData>({ totalSteps: 1, initialData: PROJECTS_INITIAL })
  const { mode, query } = flow.data

  const needle = query.trim().toLowerCase()
  const results = mode === "first-use" ? [] : PROJECTS.filter((p) => p.name.toLowerCase().includes(needle))
  const view: ProjectsView = mode === "first-use" ? "first-use" : results.length === 0 ? "no-results" : "list"

  const selectView = (next: string) => {
    if (next === "first-use") flow.patch({ mode: "first-use", query: "" })
    else if (next === "no-results") flow.patch({ mode: "list", query: NO_MATCH_QUERY })
    else flow.patch({ mode: "list", query: "" })
  }

  return (
    <FlowShell
      title="Projects empty states"
      step={0}
      totalSteps={1}
      showProgress={false}
      onReset={flow.reset}
      phoneBackground="var(--atlas-background)"
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "var(--atlas-spacing-4)",
          paddingInline: "var(--atlas-spacing-4)",
          paddingBlockEnd: "var(--atlas-spacing-6)",
        }}
      >
        {/* Review control: switches between the three situations */}
        <TabsRoot variant="segmented" size="sm" value={view} onValueChange={selectView}>
          <TabsList aria-label="Preview state">
            <TabsTrigger value="list">List</TabsTrigger>
            <TabsTrigger value="first-use">First use</TabsTrigger>
            <TabsTrigger value="no-results">No results</TabsTrigger>
          </TabsList>
        </TabsRoot>

        <header style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <h1
            style={{
              margin: 0,
              fontSize: "var(--atlas-text-h1)",
              fontWeight: "var(--atlas-font-weight-bold)",
              lineHeight: "var(--atlas-line-height-tight)",
              color: "var(--atlas-foreground)",
            }}
          >
            Projects
          </h1>
          {view !== "first-use" && (
            <Button variant="primary" size="sm" leadingIcon={<FolderPlusIcon size={16} aria-hidden="true" />}>
              New
            </Button>
          )}
        </header>

        <Input
          id="project-search"
          type="search"
          aria-label="Search projects"
          placeholder="Search projects"
          leadingIcon={<SearchIcon size={16} aria-hidden="true" />}
          value={query}
          disabled={view === "first-use"}
          onChange={(e) => flow.patch({ query: e.target.value })}
        />

        {view === "list" && (
          <ul
            aria-label="Projects"
            style={{
              listStyle: "none",
              margin: 0,
              padding: 0,
              display: "flex",
              flexDirection: "column",
              gap: "var(--atlas-spacing-2)",
            }}
          >
            {results.map((p) => (
              <ListItem key={p.id} as="li" variant="outline">
                <ListItemMedia decorative>
                  <FolderIcon size={20} aria-hidden="true" />
                </ListItemMedia>
                <ListItemContent>
                  <ListItemTitle>{p.name}</ListItemTitle>
                  <ListItemDescription>Updated {p.updated}</ListItemDescription>
                </ListItemContent>
              </ListItem>
            ))}
          </ul>
        )}

        {view === "first-use" && (
          <EmptyState
            icon={<FolderPlusIcon size={28} />}
            title="Create your first project"
            description="Projects keep related files, tasks and teammates together in one place. Start one to get organised."
          >
            <Button variant="primary" size="lg" leadingIcon={<FolderPlusIcon size={18} aria-hidden="true" />}>
              Create project
            </Button>
          </EmptyState>
        )}

        {view === "no-results" && (
          <EmptyState
            icon={<SearchXIcon size={28} />}
            title="No projects found"
            description={`Nothing matches “${query.trim()}”. Check the spelling or try a different search.`}
          >
            <Button variant="outline" size="md" onClick={() => flow.patch({ query: "" })}>
              Clear search
            </Button>
          </EmptyState>
        )}
      </div>
    </FlowShell>
  )
}

