      onReset={flow.reset}
      phoneBackground="var(--atlas-background)"
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "var(--atlas-spacing-4)",
          paddingInline: "var(--atlas-spacing-4)",
          paddingBlockEnd: "var(--atlas-spacing-6)",
        }}
      >
        {/* Review control: switches between the three situations */}
        <TabsRoot variant="segmented" size="sm" value={view} onValueChange={selectView}>
          <TabsList aria-label="Preview state">
            <TabsTrigger value="list">List</TabsTrigger>
            <TabsTrigger value="first-use">First use</TabsTrigger>
            <TabsTrigger value="no-results">No results</TabsTrigger>
          </TabsList>
        </TabsRoot>

        <header style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <h1
            style={{
              margin: 0,
              fontSize: "var(--atlas-text-h1)",
              fontWeight: "var(--atlas-font-weight-bold)",
              lineHeight: "var(--atlas-line-height-tight)",
              color: "var(--atlas-foreground)",
            }}
          >
            Projects
          </h1>
          {view !== "first-use" && (
            <Button variant="primary" size="sm" leadingIcon={<FolderPlusIcon size={16} aria-hidden="true" />}>
              New
            </Button>
          )}
        </header>

        <Input
          id="project-search"
          type="search"
          aria-label="Search projects"
          placeholder="Search projects"
          leadingIcon={<SearchIcon size={16} aria-hidden="true" />}
          value={query}
          disabled={view === "first-use"}
          onChange={(e) => flow.patch({ query: e.target.value })}
        />

        {view === "list" && (
          <ul
            aria-label="Projects"
            style={{
              listStyle: "none",
              margin: 0,
              padding: 0,
              display: "flex",
              flexDirection: "column",
              gap: "var(--atlas-spacing-2)",
            }}
          >
            {results.map((p) => (
              <ListItem key={p.id} as="li" variant="outline">
                <ListItemMedia decorative>
                  <FolderIcon size={20} aria-hidden="true" />
                </ListItemMedia>
                <ListItemContent>
                  <ListItemTitle>{p.name}</ListItemTitle>
                  <ListItemDescription>Updated {p.updated}</ListItemDescription>
                </ListItemContent>
              </ListItem>
            ))}
          </ul>
        )}

        {view === "first-use" && (
          <EmptyState
            icon={<FolderPlusIcon size={28} />}
            title="Create your first project"
            description="Projects keep related files, tasks and teammates together in one place. Start one to get organised."
          >
            <Button variant="primary" size="lg" leadingIcon={<FolderPlusIcon size={18} aria-hidden="true" />}>
              Create project
            </Button>
          </EmptyState>
        )}

        {view === "no-results" && (
          <EmptyState
            icon={<SearchXIcon size={28} />}
            title="No projects found"
            description={`Nothing matches “${query.trim()}”. Check the spelling or try a different search.`}
          >
            <Button variant="outline" size="md" onClick={() => flow.patch({ query: "" })}>
              Clear search
            </Button>
          </EmptyState>
        )}
      </div>
    </FlowShell>
  )
}

